import json
from pathlib import Path

CHOICES = ["Declarative", "Interrogative", "Imperative", "Exclamatory"]
META = {
    "subtest": "Verbal Ability",
    "module": "Sentence Structure",
    "subtopic": "Types of Sentences by Purpose",
    "tags": ["sentence structure", "sentence purpose", "grammar"],
    "category": ["Professional", "Sub-Professional"],
    "language": "English",
}

def q(question, answer, explanation, difficulty):
    return {
        **META,
        "difficulty": difficulty,
        "question": question,
        "choices": CHOICES,
        "answer": answer,
        "explanation": explanation,
    }

